const actions = [
  {
    action_name: "Complete UAT testing",
    action_owner: "Alex",
    action_status: "Open",
    priority: "High",
    days_overdue: 5
  },
  {
    action_name: "Approve cutover plan",
    action_owner: "Sarah",
    action_status: "Open",
    priority: "Critical",
    days_overdue: 3
  },
  {
    action_name: "Review migration defects",
    action_owner: "James",
    action_status: "Open",
    priority: "Medium",
    days_overdue: 0
  },
  {
    action_name: "Finalise ELS strategy",
    action_owner: "Priya",
    action_status: "Open",
    priority: "High",
    days_overdue: 7
  },
  {
    action_name: "Confirm go-live readiness",
    action_owner: "David",
    action_status: "Open",
    priority: "Critical",
    days_overdue: 0
  }
];

return actions.map(action => ({
  json: {
    project_name: "SAP Transformation",
    ...action
  }
}));

const actions = $input.all().map(item => item.json);

function classifyRisk(action) {
  const priority = String(action.priority).toLowerCase();
  const days = Number(action.days_overdue);

  if (priority === "critical" || days >= 7) {
    return "RED";
  }

  if (priority === "high" || days >= 3) {
    return "AMBER";
  }

  return "GREEN";
}

const classified = actions.map(action => ({
  ...action,
  risk_rating: classifyRisk(action)
}));

const sorted = classified.sort(
  (a, b) => b.days_overdue - a.days_overdue
);

const counts = {
  RED: sorted.filter(a => a.risk_rating === "RED").length,
  AMBER: sorted.filter(a => a.risk_rating === "AMBER").length,
  GREEN: sorted.filter(a => a.risk_rating === "GREEN").length
};

let report = "SAP PROJECT - OVERDUE ACTION REPORT\n";
report += "================================\n\n";
report += `Total overdue actions: ${sorted.length}\n`;
report += `RED: ${counts.RED} | AMBER: ${counts.AMBER} | GREEN: ${counts.GREEN}\n\n`;

sorted.forEach((action, index) => {
  report += `${index + 1}. ${action.action_name}\n`;
  report += `   Owner: ${action.action_owner}\n`;
  report += `   Priority: ${action.priority}\n`;
  report += `   Days overdue: ${action.days_overdue}\n`;
  report += `   Risk: ${action.risk_rating}\n\n`;
});

return [{
  json: {
    project_name: "SAP Transformation",
    overdue_count: sorted.length,
    risk_counts: counts,
    actions: sorted,
    report
  }
}];

const data = $input.first().json;

const recommendations = data.actions.map(action => {
  let recommendation;

  if (action.risk_rating === "RED") {
    recommendation =
      "Escalate to the project manager and workstream lead. " +
      "Confirm delivery impact, recovery owner, and target date. " +
      "Review whether a governance decision is required.";
  } else if (action.risk_rating === "AMBER") {
    recommendation =
      "Request a recovery plan from the action owner. " +
      "Review progress at the next project checkpoint.";
  } else {
    recommendation =
      "Continue routine monitoring and confirm the closure date.";
  }

  return {
    ...action,
    recommendation
  };
});

let report = "SAP PROJECT - RAID ACTION REVIEW\n";
report += "================================\n\n";

recommendations.forEach((action, index) => {
  report += `${index + 1}. ${action.action_name}\n`;
  report += `Risk: ${action.risk_rating}\n`;
  report += `Owner: ${action.action_owner}\n`;
  report += `Recommendation: ${action.recommendation}\n\n`;
});

return [{
  json: {
    project_name: data.project_name,
    overdue_count: data.overdue_count,
    risk_counts: data.risk_counts,
    recommendations,
    report
  }
}];

const raw = $input.first().json;
const ai = JSON.parse(JSON.stringify(raw.output ?? raw));

const original = $("Generate Overdue Report").first().json;
const expected = original.actions;
const errors = [];

if (!Array.isArray(expected)) {
  throw new Error("Original actions array not found");
}

const actual = Array.isArray(ai.actions) ? ai.actions : [];

if (actual.length !== expected.length) {
  errors.push(
    `Expected ${expected.length} actions, received ${actual.length}`
  );
}

for (const source of expected) {
  const matches = actual.filter(
    item => item.action_name === source.action_name
  );

  if (matches.length !== 1) {
    errors.push(
      `Missing or duplicated action: ${source.action_name}`
    );
    continue;
  }

  const item = matches[0];

  if (item.owner !== source.action_owner) {
    errors.push(`Incorrect owner: ${source.action_name}`);
  }

  if (item.risk_rating !== source.risk_rating) {
    errors.push(`Incorrect risk: ${source.action_name}`);
  }

  // Restore verified overdue days from source data.
  item.days_overdue = Number(source.days_overdue);

  if (typeof item.potential_impact !== "string" ||
      !item.potential_impact.trim()) {
    errors.push(`Missing impact: ${source.action_name}`);
  }

  if (!Array.isArray(item.recommendations) ||
      item.recommendations.length < 2) {
    errors.push(`Missing recommendations: ${source.action_name}`);
  }

  if (!Array.isArray(item.missing_information) ||
      item.missing_information.length < 1) {
    errors.push(`Missing information: ${source.action_name}`);
  }
}

const counts = original.risk_counts;

if (Number(ai.red_count) !== Number(counts.RED)) {
  errors.push("Incorrect RED count");
}

if (Number(ai.amber_count) !== Number(counts.AMBER)) {
  errors.push("Incorrect AMBER count");
}

if (Number(ai.green_count) !== Number(counts.GREEN)) {
  errors.push("Incorrect GREEN count");
}

if (typeof ai.executive_summary !== "string" ||
    !ai.executive_summary.trim()) {
  errors.push("Missing executive summary");
}

return [
  {
    json: {
      validation_status: errors.length === 0 ? "PASS" : "FAIL",
      validation_errors: errors,
      project_name: original.project_name,
      overdue_count: expected.length,
      risk_counts: counts,
      ai_analysis: ai
    }
  }
];

const data = $input.first().json;

if (data.validation_status !== "PASS") {
  throw new Error("Report blocked: validation not passed");
}

const ai = data.ai_analysis;
const actions = ai.actions;
const counts = data.risk_counts;

const reviewStatus = {
  data_validation: "PASSED",
  pm_review: "PENDING",
  distribution_approval: "NOT APPROVED"
};

const escapeHtml = (value) =>
  String(value ?? "").replace(/[&<>"']/g, c => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#39;"
  })[c]);

const list = (items) =>
  "<ul>" +
  (Array.isArray(items) ? items : [])
    .map(x => `<li>${escapeHtml(x)}</li>`)
    .join("") +
  "</ul>";

const rows = actions.map(a => `
  <tr>
    <td>
      <strong>${escapeHtml(a.action_name)}</strong>
      <div class="muted">${escapeHtml(a.affected_area)}</div>
    </td>
    <td>${escapeHtml(a.owner)}</td>
    <td>${escapeHtml(a.days_overdue)}</td>
    <td><span class="rag ${escapeHtml(a.risk_rating)}">
      ${escapeHtml(a.risk_rating)}
    </span></td>
    <td>${escapeHtml(a.potential_impact)}</td>
    <td>${list(a.recommendations)}</td>
    <td>${list(a.missing_information)}</td>
  </tr>
`).join("");

const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>SAP RAID Governance Report</title>
<style>
body {
  font-family: Arial, sans-serif;
  color: #243047;
  background: #f4f6fa;
  margin: 0;
  padding: 32px;
}
.container {
  max-width: 1250px;
  margin: auto;
  background: white;
  padding: 32px;
  border-radius: 12px;
}
h1 { margin-bottom: 5px; }
.muted { color: #667085; font-size: 13px; margin-top: 6px; }
.summary {
  background: #f0f4fa;
  padding: 18px;
  border-radius: 8px;
  margin: 20px 0;
}
.kpis { display: flex; gap: 12px; margin: 22px 0; }
.kpi {
  flex: 1;
  padding: 18px;
  border: 1px solid #e1e5ec;
  border-radius: 8px;
}
.kpi strong { display: block; font-size: 28px; }
table { width: 100%; border-collapse: collapse; font-size: 13px; }
th, td {
  padding: 13px;
  border: 1px solid #e1e5ec;
  text-align: left;
  vertical-align: top;
}
th { background: #edf1f7; }
ul { padding-left: 18px; margin: 0; }
li { margin-bottom: 7px; }
.rag {
  display: inline-block;
  padding: 5px 9px;
  border-radius: 5px;
  font-weight: bold;
}
.RED { background: #fee2e2; color: #991b1b; }
.AMBER { background: #fef3c7; color: #92400e; }
.GREEN { background: #dcfce7; color: #166534; }
.footer { margin-top: 25px; font-size: 12px; color: #667085; }
@media print {
  body { background: white; padding: 0; }
  .container { padding: 12px; }
}
</style>
</head>
<body>
<div class="container">
  <h1>SAP RAID Governance Report</h1>
  <p class="muted">
    Project: ${escapeHtml(data.project_name || "SAP Transformation")}
    | Training demonstration
  </p>

<h2>Governance Review Status</h2>
<div class="summary">
  <p><strong>Data validation:</strong> ${reviewStatus.data_validation}</p>
  <p><strong>PM review:</strong> ${reviewStatus.pm_review}</p>
  <p><strong>Distribution approval:</strong> ${reviewStatus.distribution_approval}</p>
  <p class="muted">
    AI-generated analysis must be reviewed by an authorised
    project representative before stakeholder distribution.
  </p>
</div>

  <h2>Executive Summary</h2>
  <div class="summary">
    ${escapeHtml(ai.executive_summary)}
  </div>

  <div class="kpis">
    <div class="kpi"><strong>${actions.length}</strong>Overdue actions</div>
    <div class="kpi"><strong>${counts.RED}</strong>Red risks</div>
    <div class="kpi"><strong>${counts.AMBER}</strong>Amber risks</div>
    <div class="kpi"><strong>${counts.GREEN}</strong>Green risks</div>
  </div>

  <h2>Overdue Actions and Delivery Assessment</h2>
  <table>
    <thead>
      <tr>
        <th>Action / Area</th>
        <th>Owner</th>
        <th>Days overdue</th>
        <th>RAG</th>
        <th>Potential impact</th>
        <th>Recommended follow-up</th>
        <th>Evidence gaps</th>
      </tr>
    </thead>
    <tbody>${rows}</tbody>
  </table>

  <p class="footer">
    Generated from validated fictional training data.
    RAG classifications are preliminary.
    Potential impacts require project-team verification.
    Human review is required before stakeholder distribution.
  </p>
</div>
</body>
</html>`;

return [{
  json: {
    report_title: "SAP RAID Governance Report",
    validation_status: data.validation_status,
    report_html: html,
    distribution_approved: false,
    action_count: actions.length,
    risk_counts: counts
  }
}];

const items = $input.all();

return items.map(item => {
  const data = item.json;

  // Fail safely if approval details are missing.
  if (
    data["Submit Review"] !== "Approve" ||
    !String(data["Reviewer Name"] ?? "").trim()
  ) {
    throw new Error("Valid approval and reviewer name required.");
  }

  let html = data.report_html;

  if (typeof html !== "string" || !html.includes("<!DOCTYPE html>")) {
    throw new Error("Valid HTML report is missing.");
  }

  const escapeHtml = value => String(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");

  const reviewer = escapeHtml(data["Reviewer Name"].trim());

  // Verify the original report is still awaiting review.
  if (
    !html.includes("<strong>PM review:</strong> PENDING") ||
    !html.includes("<strong>Distribution approval:</strong> NOT APPROVED")
  ) {
    throw new Error("Expected pending approval markers not found.");
  }

  html = html.replace(
    "<strong>PM review:</strong> PENDING",
    `<strong>PM review:</strong> APPROVED by ${reviewer}`
  );

  html = html.replace(
    "<strong>Distribution approval:</strong> NOT APPROVED",
    "<strong>Distribution approval:</strong> APPROVED FOR REVIEWED DISTRIBUTION"
  );

  return {
    json: {
      ...data,
      report_html: html,
      approval_status: "APPROVED",
      approved_by: data["Reviewer Name"].trim()
    }
  };
});

return $input.all().map((item, index) => {
  const data = item.json;
  const decision = String(data['Submit Review'] ?? '').trim();
  const reviewer = String(data['Reviewer Name'] ?? '').trim();
  const submittedAt = String(data.submittedAt ?? '');

  if (!['Approve', 'Reject'].includes(decision)) {
    throw new Error('Review decision must be Approve or Reject.');
  }

  if (!reviewer) {
    throw new Error('Reviewer Name is required.');
  }

  if (!submittedAt || Number.isNaN(Date.parse(submittedAt))) {
    throw new Error('A valid form submission time is required.');
  }

  return {
    json: {
      ...data,
      approval_audit: {
        audit_event_id: `${$workflow.id}:${$execution.id}:${index}`,
        execution_id: String($execution.id),
        workflow_id: String($workflow.id),
        report_title: data.report_title || 'SAP RAID Governance Report',
        decision,
        reviewer_name: reviewer,
        reviewer_identity_source: 'self_reported_form_field',
        review_comments: String(data['Review Comments'] ?? ''),
        submitted_at: submittedAt,
        recorded_at: new Date().toISOString(),
        form_mode: String(data.formMode ?? '')
      }
    },
    ...(item.binary ? { binary: item.binary } : {}),
    pairedItem: { item: index }
  };
});

return $input.all().map((savedRow, index) => {
  const original = $('Build Approval Audit').itemMatching(index);

  if (savedRow.json.id == null) {
    throw new Error('No saved audit row identifier was returned.');
  }

  if (
    savedRow.json.audit_event_id !==
    original.json.approval_audit.audit_event_id
  ) {
    throw new Error('Saved audit row does not match this review.');
  }

  return {
    json: {
      ...original.json,
      audit_storage: {
        saved: true,
        row_id: savedRow.json.id,
        created_at: savedRow.json.createdAt
      }
    },
    ...(original.binary ? { binary: original.binary } : {}),
    pairedItem: { item: index }
  };
});
